import math
import cmath
from typing import Tuple, Dict, Any

def solve_quadratic(a: float, b: float, c: float) -> Dict[str, Any]:
    """
    Solves ax^2 + bx + c = 0.
    Returns a dict with:
      - type: 'real', 'complex', 'linear', 'none', or 'infinite'
      - roots: tuple of roots (empty for 'none'/'infinite', one element for 'linear')
    """
    def is_zero(x: float, tol: float = 1e-12) -> bool:
        return abs(x) <= tol

    if is_zero(a):
        if is_zero(b):
            return {"type": "infinite" if is_zero(c) else "none", "roots": ()}
        return {"type": "linear", "roots": (-c / b,)}

    d = b * b - 4 * a * c

    if d >= 0:
        sqrt_d = math.sqrt(d)
        # Numerically stable computation for real roots
        if b >= 0:
            q = -0.5 * (b + sqrt_d)
        else:
            q = -0.5 * (b - sqrt_d)
        if not is_zero(q):
            x1 = q / a
            x2 = c / q
        else:
            # Fallback to the standard formula if q is too small
            x1 = (-b + sqrt_d) / (2 * a)
            x2 = (-b - sqrt_d) / (2 * a)
        return {"type": "real", "roots": (x1, x2)}
    else:
        # Complex conjugate roots
        sqrt_d = cmath.sqrt(d)
        x1 = (-b + sqrt_d) / (2 * a)
        x2 = (-b - sqrt_d) / (2 * a)
        return {"type": "complex", "roots": (x1, x2)}

if __name__ == "__main__":
    # Example usage
    tests = [
        (1, -3, 2),     # real roots: 1 and 2
        (1, 2, 5),      # complex roots
        (0, 2, -8),     # linear: x = 4
        (0, 0, 0),      # infinite solutions
        (0, 0, 5),      # no solution
        (1e-16, 1, 1),  # near-linear
    ]
    for coeffs in tests:
        res = solve_quadratic(*coeffs)
        print(f"{coeffs} -> {res['type']}: {res['roots']}")
